mapper.update:
update SYS_Position_User set Pu_Main_Duty=false
where PU_Id in

#{id}

mapper.select:
select p.P_ID as pId, p.D_ID as dId, p.P_Name as pName, d.D_Name as dName, c.C_Name as cName, plv.PL_Name as plName, pu.PU_ID as puId, pu.PU_Main_Duty as puMainDuty, pu.Pu_Duty as puDuty, pu.Pu_Main_Dep as puMainDep,
from SYS_User u left join SYS_Position_User pu on u.U_ID=pu.U_ID left join SYS_Position p on pu.P_ID=p.P_ID left join SYS_Department d on d.D_ID=p.D_ID left join SYS_Company c on c.C_ID=u.C_ID left join SYS_PositionLV plv on plv.PL_ID=u.PL_ID
p.P_Id is not null
and d.D_ID=#{dId}
and u.U_Name like concat('%',#{uName},'%')
order by u.${sortFiled} ${sortType}
order by u.U_CreateTime desc
limit #{start},#{size}
